Here is how to get from Lisbon airport to Casa Ribalume, added right below the stay.

```svelte file=lib/GettingThere.svelte
<script>
  import { Section, Action, Table, List, ListRow } from 'design';
  import Car from 'phosphor-svelte/lib/Car';
  import PaperPlaneTilt from 'phosphor-svelte/lib/PaperPlaneTilt';

  const options = [
    ['Metro', 'About 45 min', '1 change, then uphill walk', 'About €2 each'],
    ['Taxi from the rank', 'About 25 min', 'Outside Arrivals', 'About €20'],
    ['Guesthouse pickup', 'About 25 min', 'Driver waits with a sign', '€30 fixed']
  ];

  const steps = [
    { label: 'Red line from Aeroporto', sub: 'Ride to São Sebastião, the end of the line', time: '1' },
    { label: 'Change to the blue line', sub: 'Towards Santa Apolónia, ride to the last stop', time: '2' },
    { label: 'Walk up to Rua dos Corvelos 14', sub: 'About 10 min, steep and cobbled with bags', time: '3' }
  ];

  let booked = $state(false);
  let sent = $state(false);
</script>

<Section title="Airport to Alfama" kicker="Arrival · Fri Nov 13 · Lisbon airport to Casa Ribalume">
  <Table columns={['Way', 'Time', 'Note', 'Cost']} rows={options} pick={2} />
  <p class="m-meta">The pickup takes you to the door, which saves the climb with luggage.
Check-in opens at 15:00; bags can wait at reception if you land earlier.</p>
  <p class="m-text">If you take the metro:</p>
  <List>
    {#each steps as step, i}
      <ListRow index={i + 1} label={step.label} sub={step.sub} />
    {/each}
  </List>
  {#snippet actions()}
    <Action
      label={booked ? 'Pickup booked for 2' : 'Book guesthouse pickup'}
      sublabel="€30 fixed, share your landing time"
      icon={Car}
      primary
      disabled={booked}
      onclick={() => (booked = true)}
    />
    <Action
      label={sent ? 'Sent to Inês' : 'Send route to Inês'}
      icon={PaperPlaneTilt}
      disabled={sent}
      onclick={() => (sent = true)}
    />
  {/snippet}
</Section>
```

